# Data: should we play cricket outside today?
days = [
    {"sky": "sunny",  "wind": "weak",   "play": "yes"},
    {"sky": "sunny",  "wind": "strong", "play": "yes"},
    {"sky": "cloudy", "wind": "weak",   "play": "yes"},
    {"sky": "rainy",  "wind": "weak",   "play": "no"},
    {"sky": "rainy",  "wind": "strong", "play": "no"},
    {"sky": "cloudy", "wind": "strong", "play": "no"},
]

for feature in ["sky", "wind"]:
    print("Splitting on", feature)
    groups = {}
    for d in days:
        groups.setdefault(d[feature], []).append(d["play"])
    pure = 0
    for value, answers in groups.items():
        print("  ", value, "->", answers)
        if len(set(answers)) == 1:
            pure += len(answers)
    print("   days in pure groups:", pure, "of", len(days))

